public int calculate(String s) {
    int index = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    int num = 0;
    char sign = '+';
    while (index < s.length()) {
        if (Character.isDigit(s.charAt(index))) {
            num = num * 10 + (s.charAt(index) - '0');
        }
        if (!Character.isDigit(s.charAt(index)) && s.charAt(index) != ' ' || index == s.length() - 1) {
            switch (sign) {
                case '+' -> {
                    stack.push(num);
                    break;
                }
                case '-' -> {
                    stack.push(-num);
                    break;
                }
                case '*' -> {
                    stack.push(stack.pop() * num);
                    break;
                }
                case '/' -> {
                    stack.push(stack.pop() / num);
                    break;
                }
            }
            sign = s.charAt(index);
            num = 0;
        }
        index++;
    }
    int ans = 0;
    while (!stack.isEmpty()) {
        ans += stack.pop();
    }
    return ans;
}

public int calculate(String s) {
    int num = 0, last = 0, sum = 0;
    char sign = '+';
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (Character.isDigit(c)) {
            num = num * 10 + (c - '0');
        }
        if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
            switch (sign) {
                case '+' -> { sum += last; last = num; }
                case '-' -> { sum += last; last = -num; }
                case '*' -> { last *= num; }
                case '/' -> { last /= num; }
            }
            sign = c;
            num = 0;
        }
    }
    return sum + last;
}
